rss.channel:
{{ site.Title }}
{{ site.Home.Permalink }}
{{ site.Params.description }}
{{ site.Language.Locale | default "en-us" }}
{{ range first 15 (where site.RegularPages "Type" "journal") }}


  {{ .Title }}
  {{ .Permalink }}
  {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" }}
  {{ .Permalink }}
  {{ .Description | html }}
  {{ .Content | safeHTML }}

{{ end }}
